import{_ as e,o as r,c as t,ae as o}from"./chunks/framework.DFTT1zkb.js";const m=JSON.parse('{"title":"宿舍","description":"","frontmatter":{},"headers":[],"relativePath":"life/dormitory.md","filePath":"life/dormitory.md"}'),i={name:"life/dormitory.md"};function l(h,a,n,d,s,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="宿舍" tabindex="-1">宿舍 <a class="header-anchor" href="#宿舍" aria-label="Permalink to &quot;宿舍&quot;">​</a></h1><h2 id="人数" tabindex="-1">人数 <a class="header-anchor" href="#人数" aria-label="Permalink to &quot;人数&quot;">​</a></h2><p>均为六人间，靠门一侧为上下铺，另一侧为上床下桌</p><h2 id="床位尺寸" tabindex="-1">床位尺寸 <a class="header-anchor" href="#床位尺寸" aria-label="Permalink to &quot;床位尺寸&quot;">​</a></h2><p>1.9m*0.9m</p><h2 id="用电" tabindex="-1">用电 <a class="header-anchor" href="#用电" aria-label="Permalink to &quot;用电&quot;">​</a></h2><p>宿舍床铺下左右各两个插口，上铺左右各一个插口，需要自带插排才能满足日常用电需求</p><p>限电功率未知<s>总之就是挺大的还没用跳闸过</s>，晚上十一点熄灯不断电(小部分宿舍楼和导员有特殊要求的会断电)</p><p>每度电0.5元，每个月每个宿舍有70元免费额度，额度内不收费，免费额度不结转到次月</p><h2 id="空调" tabindex="-1">空调 <a class="header-anchor" href="#空调" aria-label="Permalink to &quot;空调&quot;">​</a></h2><p>有，非制冷模式不收费</p><p>仅在夏季制冷模式才有效，制冷模式收费0.5/小时，</p><p>仅在冬季制热模式才有效，制热模式不收费</p><p>空调计费与电费均在能耗计费平台中结算与充值，但空调计费无法使用电费的免费额度</p><h2 id="门禁" tabindex="-1">门禁 <a class="header-anchor" href="#门禁" aria-label="Permalink to &quot;门禁&quot;">​</a></h2><p>学校大门晚 8 点只进不出，宿舍楼晚 11 点锁门。</p><p>学校大门和宿舍楼均需刷脸才能进入，且每个学生只能刷脸进自己的宿舍楼。</p><h2 id="查寝" tabindex="-1">查寝 <a class="header-anchor" href="#查寝" aria-label="Permalink to &quot;查寝&quot;">​</a></h2><p>以导员要求为定，不同系不同年级均有区别，大部分导员不会亲自来寝室</p><h1 id="卫生间-浴室" tabindex="-1">卫生间 &amp; 浴室 <a class="header-anchor" href="#卫生间-浴室" aria-label="Permalink to &quot;卫生间 &amp; 浴室&quot;">​</a></h1><p>宿舍<strong>无独立浴室</strong>，有独立卫生间，每个宿舍楼层有至少一个公共浴室和至少一个公共卫生间</p><h2 id="洗衣机" tabindex="-1">洗衣机 <a class="header-anchor" href="#洗衣机" aria-label="Permalink to &quot;洗衣机&quot;">​</a></h2><p>每个宿舍楼层有至少一个公共洗手间，洗手间内有公共洗衣机</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>为了宿舍楼内的和睦和健康安全，<strong>不要使用公用洗衣机洗鞋子/内裤/袜子</strong></p></div><h1 id="热水-直饮水" tabindex="-1">热水 &amp; 直饮水 <a class="header-anchor" href="#热水-直饮水" aria-label="Permalink to &quot;热水 &amp; 直饮水&quot;">​</a></h1><p>宿舍内不允许使用热水壶、电热锅等大概率加热设备 每个宿舍都有一台直饮水机，可接热水，每个宿舍楼层都有至少一台公共热水机</p><h2 id="取水教程" tabindex="-1">取水教程 <a class="header-anchor" href="#取水教程" aria-label="Permalink to &quot;取水教程&quot;">​</a></h2><h3 id="计费标准" tabindex="-1">计费标准 <a class="header-anchor" href="#计费标准" aria-label="Permalink to &quot;计费标准&quot;">​</a></h3>',28)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
